 extends // biome-ignore lint/suspicious/noExplicitAny: this is fine\n            DrizzleRef<any, keyof Types['DrizzleRelations']> | keyof Types['DrizzleRelations'], Nullable extends boolean, ResolveReturnShape, Args extends InputFieldMap = {}, Shape = Type extends DrizzleRef<any, keyof Types['DrizzleRelations']> ? Type['$inferType'] : BuildQueryResult<Types['DrizzleRelations'], Types['DrizzleRelations'][Type & keyof Types['DrizzleRelations']], true> | {\n                $pothosQueryFor: Type | undefined;\n            }, const ConnectionInterfaces extends InterfaceParam<Types>[] = [], const EdgeInterfaces extends InterfaceParam<Types>[] = []>(options: DrizzleConnectionFieldOptions<Types, ParentShape, Type, Types['DrizzleRelations'][Type extends DrizzleRef<any, infer K> ? K : Type & keyof Types['DrizzleRelations']], ObjectRef<Types, Shape>, Nullable, Args, ResolveReturnShape, Kind>, ...args: NormalizeArgs<[\n                connectionOptions: ConnectionObjectOptions<Types, ObjectRef<Types, Shape>, false, false, DrizzleConnectionShape<Types, Shape, ParentShape, Args>, ConnectionInterfaces> | ObjectRef<Types, ShapeFromConnection<ConnectionShapeHelper<Types, Shape, false>>>,\n                edgeOptions: ConnectionEdgeObjectOptions<Types, ObjectRef<Types, Shape>, false, DrizzleConnectionShape<Types, Shape, ParentShape, Args>, EdgeInterfaces> | ObjectRef<Types, {\n                    cursor: string;\n                    node?: Shape | null | undefined;\n                }>\n            ], 0>) => FieldRef<Types, ShapeFromConnection<ConnectionShapeHelper<Types, Shape, Nullable>>> : '@pothos/plugin-relay is required to use this method';\n            drizzleFieldWithInput: 'withInput' extends PluginName ? <Param extends keyof Types['DrizzleRelations'] | [keyof Types['DrizzleRelations']] | DrizzleRef<any> | [DrizzleRef<any>], Nullable extends FieldNullability<Type>, ResolveShape, ResolveReturnShape, ArgRequired extends boolean, Fields extends InputFieldMap = {}, Args extends InputFieldMap = {}, InputName extends string = 'input', Table extends keyof Types['DrizzleRelations'] = Param extends keyof Types['DrizzleRelations'] ? Param : Param extends [keyof Types['DrizzleRelations']] ? Param[0] : Param extends DrizzleRef<any, infer T> ? T & keyof Types['DrizzleRelations'] : Param extends [DrizzleRef<any, infer T>] ? T & keyof Types['DrizzleRelations'] : never, Type extends TypeParam<Types> = ObjectRef<Types, BuildQueryResult<Types['DrizzleRelations'], Types['DrizzleRelations'][Table], true> | {\n                $pothosQueryFor: Table | undefined;\n            }>>(options: DrizzleFieldWithInputOptions<Types, ParentShape, Table, Type, Nullable, Args, Kind, ResolveShape, ResolveReturnShape, Param, InputName, Fields, boolean extends ArgRequired ? (Types & {\n                WithInputArgRequired: boolean;\n            })['WithInputArgRequired'] : ArgRequired>) => FieldRef<Types, ShapeFromTypeParam<Types, Type, Nullable>> : '@pothos/plugin-with-input is required to use this method';\n        }\n        interface ConnectionFieldOptions<Types extends SchemaTypes, ParentShape, Type extends OutputType<Types>, Nullable extends boolean, EdgeNullability extends FieldNullability<[unknown]>, NodeNullability extends boolean, Args extends InputFieldMap, ResolveReturnShape> {\n        }\n        interface ConnectionObjectOptions<Types extends SchemaTypes, Type extends OutputType<Types>, EdgeNullability extends FieldNullability<[unknown]>, NodeNullability extends boolean, Resolved, Interfaces extends InterfaceParam<Types>[] = []> {\n        }\n        interface ConnectionEdgeObjectOptions<Types extends SchemaTypes, Type extends OutputType<Types>, NodeNullability extends boolean, Resolved, Interfaces extends InterfaceParam<Types>[] = []> {\n        }\n        interface DefaultConnectionArguments {\n            first?: number | null | undefined;\n            last?: number | null | undefined;\n            before?: string | null | undefined;\n            after?: string | null | undefined;\n        }\n        interface ConnectionShapeHelper<Types extends SchemaTypes, T, Nullable> {\n        }\n        interface ScopeAuthFieldAuthScopes<Types extends SchemaTypes, Parent, Args extends {} = {}> {\n        }\n        interface ScopeAuthContextForAuth<Types extends SchemaTypes, Scopes extends {}> {\n        }\n        interface FieldWithInputBaseOptions<Types extends SchemaTypes, Args extends InputFieldMap, Fields extends InputFieldMap, InputName extends string, ArgRequired extends boolean> {\n        }\n    }\n}\nexport {};"},{moduleName:"@pothos/plugin-drizzle",content:"declare module '@pothos/plugin-drizzle' {\nimport '@pothos/plugin-drizzle/global-types';\nimport '@pothos/plugin-drizzle/field-builder';\nimport '@pothos/plugin-drizzle/schema-builder';\nimport { BasePlugin, type PothosOutputFieldConfig, type PothosTypeConfig, type SchemaTypes } from '@pothos/core';\nimport type { GraphQLFieldResolver } from 'graphql';\nexport { drizzleConnectionHelpers } from '@pothos/plugin-drizzle/connection-helpers';\nexport { DrizzleObjectFieldBuilder } from '@pothos/plugin-drizzle/drizzle-field-builder';\nexport type { DrizzleNodeRef } from '@pothos/plugin-drizzle/node-ref';\nexport type { drizzleTableKey } from '@pothos/plugin-drizzle/object-ref';\nexport * from '@pothos/plugin-drizzle/types';\nexport { drizzleTableName } from '@pothos/plugin-drizzle/types';\nexport { drizzleClientCache, getSchemaConfig, type PothosDrizzleSchemaConfig, } from '@pothos/plugin-drizzle/utils/config';\nexport { type DrizzleQueryFromInfoResult, type QueryFromInfoOptions, type QueryFromInfoResult, type QueryFromInfoReturn, queryFromInfo, } from '@pothos/plugin-drizzle/utils/map-query';\nexport type { SelectionMap } from '@pothos/plugin-drizzle/utils/selections';\ndeclare const pluginName = \"drizzle\";\nexport default pluginName;\nexport declare class PothosDrizzlePlugin<Types extends SchemaTypes> extends BasePlugin<Types> {\n    onTypeConfig(typeConfig: PothosTypeConfig): PothosTypeConfig;\n    onOutputFieldConfig(fieldConfig: PothosOutputFieldConfig<Types>): PothosOutputFieldConfig<Types> | null;\n    wrapResolve(resolver: GraphQLFieldResolver<unknown, Types['Context'], object, unknown>, fieldConfig: PothosOutputFieldConfig<Types>): GraphQLFieldResolver<unknown, Types['Context'], object>;\n}\n}"},{moduleName:"@pothos/plugin-drizzle/interface-ref",content:"declare module '@pothos/plugin-drizzle/interface-ref' {\nimport { InterfaceRef, type SchemaTypes } from '@pothos/core';\nimport type { DrizzleNodeRef } from '@pothos/plugin-drizzle/node-ref';\nimport { type DrizzleObjectRef, drizzleTableKey } from '@pothos/plugin-drizzle/object-ref';\nexport type DrizzleRef<Types extends SchemaTypes, Table extends keyof Types['DrizzleRelations'] = keyof Types['DrizzleRelations'], T = {}> = DrizzleInterfaceRef<Types, Table, T> | DrizzleObjectRef<Types, Table, T> | DrizzleNodeRef<Types, Table, T>;\nexport declare class DrizzleInterfaceRef<Types extends SchemaTypes, Table extends keyof Types['DrizzleRelations'] = keyof Types['DrizzleRelations'], T = {}> extends InterfaceRef<Types, T | {\n    $pothosQueryFor: Table | undefined;\n}, T> {\n    [drizzleTableKey]: Types['DrizzleRelations'][Table];\n    tableName: string;\n    constructor(name: string, tableName: string);\n}\n}"},{moduleName:"@pothos/plugin-drizzle/model-loader",content:"declare module '@pothos/plugin-drizzle/model-loader' {\nimport { type MaybePromise, type SchemaTypes } from '@pothos/core';\nimport { type AnyTable, type Column, type SQL, type TableRelationalConfig } from 'drizzle-orm';\nimport type { GraphQLResolveInfo } from 'graphql';\nimport { type DrizzleAdapter, type DrizzleNode, type DrizzlePlan, type DrizzlePlayedPlan } from '@pothos/plugin-drizzle/utils/adapter';\nimport { type PothosDrizzleSchemaConfig } from '@pothos/plugin-drizzle/utils/config';\ninterface ResolvablePromise<T> {\n    promise: Promise<T>;\n    resolve: (value: T) => void;\n    reject: (err: unknown) => void;\n}\nexport declare class ModelLoader {\n    context: object;\n    builder: PothosSchemaTypes.SchemaBuilder<never>;\n    modelName: string;\n    rowCache: WeakMap<object, Map<string, MaybePromise<DrizzlePlayedPlan>>>;\n    planCache: WeakMap<object, Map<string, MaybePromise<DrizzlePlan>>>;\n    staged: Set<{\n        root: DrizzleNode;\n        models: Map<object, ResolvablePromise<Record<string, unknown> | null>>;\n    }>;\n    config: PothosDrizzleSchemaConfig;\n    adapter: DrizzleAdapter;\n    table: TableRelationalConfig;\n    columns: Column[];\n    private columnNames;\n    primaryKey: Column[];\n    selectSQL: (table: AnyTable<{}>) => SQL;\n    constructor(context: object, builder: PothosSchemaTypes.SchemaBuilder<never>, modelName: string, columns?: Column[]);\n    static forModel<Types extends SchemaTypes>(modelName: string, builder: PothosSchemaTypes.SchemaBuilder<Types>, columns?: Column[]): import(\"@pothos/core\").ContextCache<ModelLoader, object, []>;\n    sqlForModel(model: object): string | number | (string | number)[];\n    getSelection(info: GraphQLResolveInfo): MaybePromise<DrizzlePlayedPlan>;\n    getSelectionForField(info: GraphQLResolveInfo, typeName: string): MaybePromise<DrizzlePlan>;\n    /**\n     * `model` reloaded with the selection of the field `info` resolves. A synchronous selection\n     * stages synchronously, so every row resolved in a tick joins the same batch; only a selection\n     * with an async select beneath the field waits for it.\n     */\n    loadSelection(info: GraphQLResolveInfo, model: object): Promise<Record<string, unknown> | null>;\n    private loadWith;\n    /** A node loaded by id with the selection beneath the field `info` resolves, as `returnType`. */\n    loadSelectionForField(info: GraphQLResolveInfo, model: object, returnType: string): Promise<Record<string, unknown> | null>;\n    private loadFieldWith;\n    stageQuery(played: Pick<DrizzlePlayedPlan, 'root'>, model: object): Promise<Record<string, unknown> | null>;\n    initLoad(played: Pick<DrizzlePlayedPlan, 'root'>, model: object): Promise<Record<string, unknown> | null>;\n}\n/** Matches `ScopeAuthParentLoader` in @pothos/plugin-scope-auth, which this plugin can't import. */\ntype ScopeAuthParentLoader = (parent: unknown, context: object, info: GraphQLResolveInfo) => MaybePromise<unknown>;\n/**\n * The parent scope-auth's checks see for a type: the row when it has every top-level key of the\n * type's selection (`root`, planned from it), otherwise the row reloaded with it.\n */\nexport declare function typeParentLoader(loaders: (context: object) => ModelLoader, root: DrizzleNode): ScopeAuthParentLoader;\nexport {};\n}"},{moduleName:"@pothos/plugin-drizzle/node-ref",content:"declare module '@pothos/plugin-drizzle/node-ref' {\nimport type { SchemaTypes } from '@pothos/core';\nimport { DrizzleObjectRef } from '@pothos/plugin-drizzle/object-ref';\nexport declare const relayIDShapeKey: unique symbol;\nexport declare class DrizzleNodeRef<Types extends SchemaTypes, Table extends keyof Types['DrizzleRelations'] = keyof Types['DrizzleRelations'], T = {}, IDShape = string> extends DrizzleObjectRef<Types, Table, T> {\n    [relayIDShapeKey]: IDShape;\n    parseId: ((id: string, ctx: object) => IDShape) | undefined;\n    constructor(name: string, tableName: string, options: {\n        parseId?: (id: string, ctx: object) => IDShape;\n    });\n}\n}"},{moduleName:"@pothos/plugin-drizzle/object-ref",content:"declare module '@pothos/plugin-drizzle/object-ref' {\nimport { abstractReturnShapeKey, ObjectRef, type SchemaTypes } from '@pothos/core';\nimport type { WithBrand } from '@pothos/plugin-drizzle/types';\nexport declare const drizzleTableKey: unique symbol;\nexport declare class DrizzleObjectRef<Types extends SchemaTypes, Table extends keyof Types['DrizzleRelations'] = keyof Types['DrizzleRelations'], T = {}> extends ObjectRef<Types, T | {\n    $pothosQueryFor: Table | undefined;\n}, T> {\n    [drizzleTableKey]: Types['DrizzleRelations'][Table];\n    [abstractReturnShapeKey]: WithBrand<T>;\n    tableName: string;\n    constructor(name: string, tableName: string);\n    addBrand<V extends T | T[]>(value: V): V extends T[] ? {\n        [K in keyof V]: WithBrand<V[K]>;\n    } : WithBrand<V>;\n    hasBrand(value: unknown): boolean;\n}\n}"},{moduleName:"@pothos/plugin-drizzle/schema-builder",content:"declare module '@pothos/plugin-drizzle/schema-builder' {\nexport {};\n}"},{moduleName:"@pothos/plugin-drizzle/types",content:"declare module '@pothos/plugin-drizzle/types' {\nimport { type ArgumentRef, type CheckAsyncSelection, type DistributeOmit, type FieldKind, type FieldMap, type FieldNullability, type FieldOptionsFromKind, type InferredFieldOptionKeys, type InferredFieldOptionsByKind, type InputFieldMap, type InputFieldsFromShape, type InputShapeFromFields, type InterfaceParam, type InterfaceRef, type InterfaceTypeOptions, type ListResolveValue, type MaybeAsyncSelection, type MaybePromise, type Merge, type Normalize, type ObjectRef, type ObjectTypeOptions, type OutputShape, type OutputType, type SchemaTypes, type ShapeFromTypeParam, type TypeParam, typeBrandKey } from '@pothos/core';\nimport type { IndirectInclude, IndirectPathSegment, PathSegment } from '@pothos/selection-mapper';\nimport type { AnyRelations, BuildQueryResult, Column, DBQueryConfig, Many, Relation, SQL, SQLWrapper, Table, TableRelationalConfig } from 'drizzle-orm';\nimport type { FieldNode, GraphQLResolveInfo } from 'graphql';\nimport type { DrizzleObjectFieldBuilder } from '@pothos/plugin-drizzle/drizzle-field-builder';\nimport type { DrizzleRef } from '@pothos/plugin-drizzle/interface-ref';\nimport type { DrizzleRelationsHint } from '@pothos/plugin-drizzle/utils/refs';\nimport type { SelectionMap } from '@pothos/plugin-drizzle/utils/selections';\n/**\n * A segment of a `path` given to `queryFromInfo` or `nestedSelection`: a field name, or\n * `{ name, type }` to pin the type the field must be selected under (a fragment on it).\n */\nexport type { IndirectInclude, IndirectPathSegment, PathSegment };\nexport interface FieldPathInfo {\n    field: string;\n    alias: string;\n    parentType: string;\n    isList: boolean;\n}\nexport interface PathInfo {\n    path: string[];\n    segments: FieldPathInfo[];\n}\nexport type DrizzleClient<TCountSource = Table | SQL | SQLWrapper, TTable = Extract<TCountSource, Table>> = {\n    readonly _: {\n        readonly relations: AnyRelations;\n    };\n    query: Record<string, {\n        findMany: (config: never) => PromiseLike<Record<string, unknown>[]>;\n    }>;\n    $count: (source: TCountSource, filter?: SQL) => SQL<number>;\n    /** Core SQL construction used for relation predicates and counts; it does not execute a query. */\n    select: (fields: Record<string, SQL>) => {\n        from(table: TTable): {\n            innerJoin(table: TTable, on: SQL): {\n                where: (filter?: SQL) => SQLWrapper;\n            };\n            where: (filter?: SQL) => SQLWrapper;\n        };\n    };\n};\ntype GetTableConfigFn<TTable = Table> = (table: TTable) => {\n    primaryKeys: {\n        readonly columns: Column[];\n    }[];\n    uniqueConstraints?: {\n        readonly columns: Column[];\n    }[];\n    readonly columns: Column[];\n};\ntype AnyRelationTable<Types extends SchemaTypes> = Types['DrizzleRelations'][keyof Types['DrizzleRelations']]['table'];\ntype DrizzleClientForTypes<Types extends SchemaTypes> = Omit<DrizzleClient<AnyRelationTable<Types> | SQL | SQLWrapper, Table extends AnyRelationTable<Types> ? Table : never>, 'query'> & {\n    query: Record<string, {\n        findMany: unknown;\n    }>;\n};\ntype DrizzlePluginBaseOptions = {\n    maxConnectionSize?: number;\n    defaultConnectionSize?: number;\n    skipDeferredFragments?: boolean;\n    /**\n     * When `true` (the default), the `totalCount` of a `relatedConnection` applies the `where`\n     * returned by the field's `query`, so it counts the same rows the connection paginates. Set to\n     * `false` to count every related row regardless of the filter.\n     */\n    filterConnectionTotalCount?: boolean;\n};\nexport type DrizzlePluginOptions<Types extends SchemaTypes> = DrizzlePluginBaseOptions & ({\n    client: DrizzleClientForTypes<Types>;\n    getTableConfig: GetTableConfigFn<AnyRelationTable<Types>>;\n    relations?: Types['DrizzleRelations'];\n} | {\n    client: (ctx: Types['Context']) => DrizzleClientForTypes<Types>;\n    getTableConfig: GetTableConfigFn<AnyRelationTable<Types>>;\n    relations: Types['DrizzleRelations'];\n});\nexport declare const drizzleTableName: unique symbol;\n/** Marks a parent shape with its table name. */\nexport interface DrizzleTableNameBrand<Table> {\n    [drizzleTableName]?: Table;\n}\ntype NameOrVariant = {\n    name?: never;\n    variant?: string;\n} | {\n    name?: string;\n    variant?: never;\n};\nexport type DrizzleObjectOptions<Types extends SchemaTypes, Table extends keyof Types['DrizzleRelations'], Shape, Selection, Interfaces extends InterfaceParam<Types>[]> = Omit<ObjectTypeOptions<Types, ObjectRef<Types, Shape>, Shape, Interfaces>, 'fields'> & NameOrVariant & {\n    select?: Selection;\n    fields?: (t: DrizzleObjectFieldBuilder<Types, Types['DrizzleRelations'][Table], Shape & DrizzleTableNameBrand<Table>>) => FieldMap;\n};\nexport type DrizzleInterfaceOptions<Types extends SchemaTypes, Table extends keyof Types['DrizzleRelations'], Shape, Selection, Interfaces extends InterfaceParam<Types>[]> = Omit<InterfaceTypeOptions<Types, InterfaceRef<Types, Shape>, Shape, Interfaces>, 'fields'> & NameOrVariant & {\n    select?: Selection;\n    fields?: (t: DrizzleObjectFieldBuilder<Types, Types['DrizzleRelations'][Table], Shape & DrizzleTableNameBrand<Table>>) => FieldMap;\n};\nexport type DrizzleNodeOptions<Types extends SchemaTypes, Table extends keyof Types['DrizzleRelations'], Shape, Selection, Interfaces extends InterfaceParam<Types>[], IDColumns> = NameOrVariant & Omit<PothosSchemaTypes.ObjectTypeOptions<Types, Shape> | PothosSchemaTypes.ObjectTypeWithInterfaceOptions<Types, Shape, Interfaces>, 'fields' | 'isTypeOf'> & {\n    id: Omit<FieldOptionsFromKind<Types, Shape, 'ID', false, {}, 'Object', OutputShape<Types, 'ID'>, MaybePromise<OutputShape<Types, 'ID'>>>, 'args' | 'nullable' | 'type' | InferredFieldOptionKeys> & {\n        column: IDColumns & (Column | Column[] | ((columns: Types['DrizzleRelations'][Table]['table']) => Column | Column[]));\n    };\n    select?: Selection;\n    fields?: (t: DrizzleObjectFieldBuilder<Types, Types['DrizzleRelations'][Table], Shape & DrizzleTableNameBrand<Table>>) => FieldMap;\n} & NameOrVariant;\nexport type ShapeFromIdColumns<Types extends SchemaTypes, Table extends keyof Types['DrizzleRelations'], IDColumns> = IDColumns extends Column ? IDColumns['_']['data'] : IDColumns extends Column[] ? {\n    [K in IDColumns[number]['_']['name']]: Extract<IDColumns[number], {\n        _: {\n            name: K;\n        };\n    }>['_']['data'];\n} : IDColumns extends ((...args: any[]) => infer R extends Column | Column[]) ? ShapeFromIdColumns<Types, Table, R> : never;\nexport type DrizzleFieldOptions<Types extends SchemaTypes, ParentShape, Table extends keyof Types['DrizzleRelations'], Type extends TypeParam<Types>, Nullable extends FieldNullability<Type>, Args extends InputFieldMap, Kind extends FieldKind, ResolveShape, ResolveReturnShape, Param> = Omit<FieldOptionsFromKind<Types, ParentShape, Type, Nullable, Args, Kind, ResolveShape, ResolveReturnShape>, 'type' | InferredFieldOptionKeys> & {\n    type: Param | DrizzleRelationsHint<Types, true>;\n    resolve: (query: <T = {}>(selection?: T & QueryForDrizzleField<Types, Param, Table>) => Omit<T, 'columns' | 'extra'> & {\n        columns: T extends {\n            columns: infer C extends {};\n        } ? C : {};\n        extras: {\n            $pothosQueryFor: SQL<Table | undefined>;\n        } & (T extends {\n            extra: infer E;\n        } ? E : {});\n    }, parent: ParentShape, args: InputShapeFromFields<Args>, ctx: Types['Context'], info: GraphQLResolveInfo) => MaybePromise<ShapeFromTypeParam<Types, Type, Nullable>>;\n};\nexport type DrizzleFieldWithInputOptions<Types extends SchemaTypes, ParentShape, Table extends keyof Types['DrizzleRelations'], Type extends TypeParam<Types>, Nullable extends FieldNullability<Type>, Args extends InputFieldMap, Kind extends FieldKind, ResolveShape, ResolveReturnShape, Param, InputName extends string, Fields extends InputFieldMap, ArgRequired extends boolean> = DistributeOmit<DrizzleFieldOptions<Types, ParentShape, Table, Type, Nullable, Args & {\n    [K in InputName]: ArgumentRef<Types, InputShapeFromFields<Fields> | (true extends ArgRequired ? never : null | undefined)>;\n}, Kind, ResolveShape, ResolveReturnShape, Param>, 'args'> & PothosSchemaTypes.FieldWithInputBaseOptions<Types, Args, Fields, InputName, ArgRequired>;\nexport type DrizzleObjectFieldOptions<Types extends SchemaTypes, ParentShape, Type extends TypeParam<Types>, Nullable extends FieldNullability<Type>, Args extends InputFieldMap, Select, ResolveReturnShape, ShapeWithSelection = Normalize<Omit<unknown extends Select ? ParentShape : BuildQueryResult<Types['DrizzleRelations'], ExtractTable<Types, ParentShape>, Record<string, unknown> & Select extends (...args: any[]) => infer R ? Awaited<R> & {\n    columns: {};\n} : Select & {\n    columns: {};\n}> & ParentShape, typeof drizzleTableName>>> = PothosSchemaTypes.ObjectFieldOptions<Types, ShapeWithSelection, Type, Nullable, Args, ResolveReturnShape> & InferredFieldOptionsByKind<Types, Types['InferredFieldOptionsKind'], ShapeWithSelection, Type, Nullable, Args, ResolveReturnShape> & {\n    /**\n     * What the field needs from its parent row. With `AsyncSelections: true` the function may be\n     * async, and `nestedSelection` is then a promise when a selection beneath it is async, and\n     * must be awaited.\n     */\n    select?: Select & CheckAsyncSelection<Types, Select> & (DBQueryConfig<'one', Types['DrizzleRelations'], ExtractTable<Types, ParentShape>> | ((args: InputShapeFromFields<Args>, ctx: Types['Context'], nestedSelection: NestedSelectionFn<Types, Type, Args>) => MaybeAsyncSelection<Types, DBQueryConfig<'one', Types['DrizzleRelations'], ExtractTable<Types, ParentShape>>>));\n};\n/** The table a field's type param names: a drizzle ref, or a list of one. */\nexport type TableForTypeParam<Types extends SchemaTypes, Type> = Type extends [infer Item] ? TableForTypeParam<Types, Item> : Type extends DrizzleRef<any, infer Table> ? Table & keyof Types['DrizzleRelations'] : never;\n/**\n * The query config for the table a field's type param names (a `many` config for a list field),\n * or never when the type has no table.\n */\nexport type QueryForTypeParam<Types extends SchemaTypes, Type> = TableForTypeParam<Types, Type> extends infer Table ? [Table] extends [never] ? never : DBQueryConfig<Type extends [unknown] ? 'many' : 'one', Types['DrizzleRelations'], Types['DrizzleRelations'][Table & keyof Types['DrizzleRelations']]> : never;\n/**\n * What `nestedSelection` returns: the query config for the field's table, keeping the keys of\n * the given selection as they were given (so `columns` in it still narrow the parent shape).\n * With no selection, or `true`, it is the config itself. A field whose type has no table keeps\n * the selection it was given.\n */\nexport type NestedSelectionResult<Types extends SchemaTypes, Type, Selection> = [\n    QueryForTypeParam<Types, Type>\n] extends [never] ? Selection : Selection extends boolean ? QueryForTypeParam<Types, Type> : Normalize<Omit<QueryForTypeParam<Types, Type>, keyof Selection> & Selection>;\n/**\n * The callback a field's `select` function plans the selection beneath the field with: `path`\n * walks a field nested under the field's type, `type` names the type the selection is read as.\n * It also carries the `PathInfo` of the field being planned. The selection is typed by the\n * field's table when it has